// Hand-authored — NOT generated by prism, and prism will not overwrite it
// (it only replaces files carrying its header). See the React wrapper for the
// reasoning: virtualization is the one case where the wrapper has to own the
// rows, because only Preact can create a Preact row.
import { h, type ComponentChildren, type FunctionComponent } from 'preact';
import { useCallback, useEffect, useRef, useState } from 'preact/hooks';
import '@arclux/arc-ui/virtual-list';

export interface VirtualListProps {
  /** The full data array. Only the visible slice is rendered. */
  items: unknown[];
  /** Renders one row. Called only for rows currently on screen. */
  renderItem: (item: never, index: number) => ComponentChildren;
  /** Row height in pixels. Must match what actually renders. */
  itemHeight?: number;
  /** Rows rendered above and below the viewport, to cover fast scrolling. */
  overscan?: number;
  /** Called when the visible range changes. `end` is exclusive. */
  onRangeChange?: (range: { start: number; end: number }) => void;
  class?: string;
  style?: string | Record<string, string | number>;
  id?: string;
}

type ListElement = HTMLElement & {
  items?: unknown[];
  visibleRange?: { start: number; end: number };
};

export const VirtualList: FunctionComponent<VirtualListProps> = ({
  items,
  renderItem,
  itemHeight = 40,
  overscan = 5,
  onRangeChange,
  ...rest
}) => {
  const ref = useRef<ListElement>(null);
  const [range, setRange] = useState({ start: 0, end: 0 });

  // An array has to be set as a property; as an attribute it would stringify.
  useEffect(() => {
    const el = ref.current;
    if (el) el.items = items;
  }, [items]);

  const onRange = useCallback((e: Event) => {
    const { start, end } = (e as CustomEvent).detail;
    setRange({ start, end });
    onRangeChange?.({ start, end });
  }, [onRangeChange]);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.addEventListener('arc-range-change', onRange);
    // The element may have measured before this effect ran, in which case its
    // first range event is already spent.
    if (el.visibleRange) setRange({ ...el.visibleRange });
    return () => el.removeEventListener('arc-range-change', onRange);
  }, [onRange]);

  const rows: ComponentChildren[] = [];
  for (let i = range.start; i < Math.min(range.end, items.length); i++) {
    rows.push(h('div', { key: i, slot: `item-${i}` }, renderItem(items[i] as never, i)));
  }

  return h('arc-virtual-list', { ref, 'item-height': itemHeight, overscan, ...rest }, rows);
};
